import{z as r,x as l,o as e,c as p,q as A,j as i,D as B,d as E,s as n,S as o,b as t}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"Grossman–Stiglitz 悖论","description":"","frontmatter":{"title":"Grossman–Stiglitz 悖论","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/grossman-stiglitz.md","filePath":"econ/grossman-stiglitz.md","lastUpdated":1791413859000}'),m={name:"econ/grossman-stiglitz.md"};function d(c,a,F,g,C,h){const s=l("Mermaid");return e(),p("div",null,[a[2]||(a[2]=A('<h1 id="grossman–stiglitz-悖论" tabindex="-1">Grossman–Stiglitz 悖论 <a class="header-anchor" href="#grossman–stiglitz-悖论" aria-label="Permalink to &quot;Grossman–Stiglitz 悖论&quot;">​</a></h1><div class="epigraph"><p>若价格已经把昂贵信息完全写进去，就没有人愿意付费去生产它；于是价格不能完全揭示。</p><footer>—— Grossman and Stiglitz, On the Impossibility of Informationally Efficient Markets, American Economic Review, 1980</footer></div><p><a href="/econ/limited-attention-pead">上一课</a>把公告后的漂移写成注意力预算：公开信号已经在世上，只是没被读完。本课换一条缝，而且是理性均衡里的缝。缺口不是再写一遍处理成本，而是：<strong>生产</strong>信息要花固定成本时，完全揭示与正的采集激励不能同时成立。后课默认已经读完：信息有效的工作版本是「相对采集成本，利润被压到近零」，不是字面的充分统计价格。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><a href="/econ/emh">有效市场</a>已经点过这条悖论的名字，但没有把均衡写出来。设有一张风险资产，清算值 \\(\\theta\\) 未知。一部分人可以花成本 \\(c\\) 看见关于 \\(\\theta\\) 的信号，其余人只看价格。若均衡价格 \\(p\\) 是 \\(\\theta\\) 的充分统计，未知情者从 \\(p\\) 里读到与知情者同样的东西，知情者的毛租金为零，付 \\(c\\) 的人严格更差。于是没人买信号，\\(p\\) 里没有私人信息可揭示——与「\\(p\\) 已完全揭示」矛盾。</p><p>缺口是把这句话收成有噪声的理性预期均衡（REE），而不是用公告漂移当否证。有限注意力攻击的是处理；本课攻击的是激励。两条缝可以并存，对象不同。</p><p><span class="marginnote">术语翻译：「充分统计」意思是看价格就够了——价格里已打包了知情者知道的一切；「搭便车」则是不付采集成本、只从别人交易推动的价格里白捡信息。悖论正是两者相克：人人都能搭便车，就没人开车（付费采集）。</span></p><p><span class="marginnote">Grossman and Stiglitz, <em>AER</em> 70(3), 1980。CARA 加正态信号、再加随机供给，是为了让价格部分揭示而仍有闭式需求。随机供给不是限价簿上的深度，是竞争性噪声。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>CARA 偏好、正态 \\((\\theta,s)\\)、外生随机供给 \\(z\\)。知情者用 \\((s,p)\\) 更新，未知情者只用 \\(p\\)。市场出清给出 \\(p\\) 关于 \\((s,z)\\) 的线性函数。\\(z\\) 使 \\(p\\) 不是 \\(s\\) 的一一映射：看见 \\(p\\) 高，分不清是好信号还是供给少。于是价格<strong>部分</strong>揭示，知情者仍保有一块信息租金，刚好在均衡里补偿 \\(c\\)。知情者比例 \\(\\lambda\\) 由无差异条件钉住：买信号的期望效用等于不买。</p><p>\\(\\lambda\\) 升则 \\(p\\) 更接近 \\(s\\)，\\(c\\) 的净回报下降——采集是策略替代。\\(c\\to 0\\) 时 \\(\\lambda\\) 可以很大，揭示可以很深，但 \\(c=0\\) 才允许完全揭示；任何严格正的 \\(c\\) 都留下一层噪声。这就是「不可能」的精确含义：不是市场不能反映信息，而是不能在有成本时<strong>完全</strong>反映还让采集发生。</p><p><span class="marginnote">数字实例：花 1000 元买研究报告平均能多赚 800 元。若只有 10 个人买，价格几乎不动，信息优势全额到手；若 10 万人都买，他们下单时就把信息写进了价格，没花钱的人看价格免费读到——你那 1000 元买的「抢先」被稀释到不值 800 元，付费意愿随之下降。</span></p>',12)),(e(),i(o,null,{default:B(()=>[n(s,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20FULL%5B%22%E5%AE%8C%E5%85%A8%E6%8F%AD%E7%A4%BA%22%5D%20--%3E%20ZERO%5B%22%E7%9F%A5%E6%83%85%E7%A7%9F%E9%87%91%E4%B8%BA%E9%9B%B6%22%5D%0A%20%20ZERO%20--%3E%20NOBUY%5B%22%E6%97%A0%E4%BA%BA%E4%BB%98%20c%22%5D%0A%20%20NOBUY%20--%3E%20EMPTY%5B%22%E4%BB%B7%E6%A0%BC%E6%97%A0%E5%8F%AF%E6%8F%AD%E7%A4%BA%22%5D%0A%20%20EMPTY%20--%3E%20CONTRA%5B%22%E4%B8%8E%E5%AE%8C%E5%85%A8%E6%8F%AD%E7%A4%BA%E7%9F%9B%E7%9B%BE%22%5D%0A%20%20NOISE%5B%22%E4%BE%9B%E7%BB%99%E5%99%AA%E5%A3%B0%22%5D%20--%3E%20PART%5B%22%E9%83%A8%E5%88%86%E6%8F%AD%E7%A4%BA%22%5D%0A%20%20PART%20--%3E%20RENT%5B%22%E7%A7%9F%E9%87%91%E8%A1%A5%E5%81%BF%20c%22%5D%0A"})]),fallback:B(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("p",null,[E("不要把 \\(z\\) 写成做市商存货或买卖队列。"),t("a",{href:"/econ/to-limit-order-book"},"到限价簿"),E("已经声明：本栏的价格是出清对象，不是协议。这里的噪声是为了让竞争性 REE 存在，不是微观结构。")],-1)),a[4]||(a[4]=t("h2",{id:"机制",tabindex:"-1"},[E("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=t("p",null,"机制是激励相容，不是集体智慧失灵。价格越干净，搭便车越便宜，采集越少，价格越脏——负反馈把均衡按在内点。社会最优采集通常多于这个内点：私人算的是相对 \\(p\\) 的租金，社会算的是配置对 \\(\\theta\\) 的敏感；竞争性价格把信息泄漏给未付费的人，采集被供给不足。这与 EMH 的工作版本一致：相对 \\(c\\)，没有人能靠再买一份已经写进 \\(p\\) 的信号赚经济利润。",-1)),(e(),i(o,null,{default:B(()=>[n(s,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20DIRTY%5B%22%E4%BB%B7%E6%A0%BC%E8%84%8F%EF%BC%9A%E6%8F%AD%E7%A4%BA%E5%B0%91%22%5D%20--%3E%20CHEAP%5B%22%E7%A7%81%E4%BA%BA%E4%BF%A1%E5%8F%B7%E7%9B%B8%E5%AF%B9%E6%9B%B4%E5%80%BC%E9%92%B1%22%5D%0A%20%20CHEAP%20--%3E%20BUY%5B%22%E6%9B%B4%E5%A4%9A%E4%BA%BA%E4%BB%98%E8%B4%B9%E4%B9%B0%E4%BF%A1%E5%8F%B7%EF%BC%8C%CE%BB%20%E4%B8%8A%E5%8D%87%22%5D%0A%20%20BUY%20--%3E%20CLEAN%5B%22%E4%BB%B7%E6%A0%BC%E5%8F%98%E5%B9%B2%E5%87%80%EF%BC%9A%E6%8F%AD%E7%A4%BA%E5%8F%98%E5%A4%9A%22%5D%0A%20%20CLEAN%20--%3E%20FREE%5B%22%E6%90%AD%E4%BE%BF%E8%BD%A6%E6%9B%B4%E4%BE%BF%E5%AE%9C%EF%BC%9A%E7%9C%8B%E4%BB%B7%E6%A0%BC%E5%B7%B2%E5%A4%9F%22%5D%0A%20%20FREE%20--%3E%20QUIT%5B%22%E4%BB%98%E8%B4%B9%E7%9A%84%E4%BA%BA%E5%87%8F%E5%B0%91%EF%BC%8C%CE%BB%20%E4%B8%8B%E9%99%8D%22%5D%0A%20%20QUIT%20--%3E%7C%22%E4%BB%B7%E6%A0%BC%E9%87%8D%E6%96%B0%E5%8F%98%E8%84%8F%22%7C%20DIRTY%0A%20%20EQ%5B%22%E8%B4%9F%E5%8F%8D%E9%A6%88%E5%81%9C%E5%9C%A8%E5%9D%87%E8%A1%A1%20%CE%BB*%EF%BC%9A%E7%A7%9F%E9%87%91%E6%81%B0%E5%A5%BD%E8%A1%A5%E5%81%BF%20c%22%5D%0A"})]),fallback:B(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=A('<p>上一课的注意力是另一层供给不足：即便 \\(c\\) 已付、信号已公开，读的时间仍稀缺。本课假定读得完，只问买不买。后课 Hellwig 把「有限个知情者」换成连续统，竞争性假设才站稳。</p><p><span class="marginnote">完全揭示均衡在 \\(c\\gt 0\\) 时不是均衡，不需要非理性。噪声交易、随机禀赋、生命期对冲需求，都可以扮演 \\(z\\) 的角色；精神是残差不确定性，不是行为偏差。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要把悖论写成「市场无效」：部分揭示的 \\(p\\) 对 \\(\\mathcal{F}_p\\)（价格生成的信息）仍可以有效，只是 \\(\\mathcal{F}_p\\) 严格小于知情者的 \\(\\mathcal{F}\\)。也不要把随机供给写成限价簿冲击——量化栏才给冲击一个队列。本课不估计知情者比例，不把 PEAD 的窗口拿来当 \\(c\\) 的度量。</p><p><span class="marginnote">常见误区：把「信息不可能完全有效」读成「市场没用、研究无用」。GS 说的只是一件精确的事：只要采集有成本，价格就不能既完全揭示、又让采集者回本。工作均衡是「部分揭示、超额利润被压到近零」——价格对自己生成的信息集仍然有效。</span></p><p>下一课把同一套 CARA–正态放到<strong>连续统</strong>竞争里：个人对价格无影响，Hellwig 的 REE 才是价格接受的版本。GS 原文的有限知情者已经近于竞争，但存在与揭示的数学要到连续统才干净。</p><p>后课默认：有成本的私人信息与完全揭示不能共存；工作均衡是部分揭示，采集比例内生。有效是相对价格信息集，不是相对全部私人信号。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>完全揭示使信息租金为零，无人付 \\(c\\)，故完全揭示不是有成本采集的均衡。</li><li>供给噪声给出部分揭示，租金补偿 \\(c\\)，知情者比例内生。</li><li>这是激励缝，不是注意力缝；也不改写限价簿。</li><li>出处：Grossman and Stiglitz, <em>AER</em> 1980。</li></ul>',9))])}const T=r(m,[["render",d]]);export{f as __pageData,T as default};
